<?php
require_once '../config.php';requireAdmin();
$counts=['products'=>(int)$pdo->query("SELECT COUNT(*) FROM products WHERE active=1")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders")->fetchColumn()];
$orders=$pdo->query("SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 20")->fetchAll();
$pageTitle='Painel administrativo';include '../includes/header.php';?>
<div class="page-head"><div class="container"><div class="section-kicker">CENTRAL DE COMANDO</div><h1>PAINEL ADMINISTRATIVO</h1></div></div><section class="section"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><h2 class="admin-title">VISÃO GERAL</h2><a class="btn-red" href="products.php">GERENCIAR PRODUTOS</a></div><div class="row g-3 mb-5"><?php foreach(['Produtos ativos'=>$counts['products'],'Pedidos'=>$counts['orders'],'Clientes'=>$counts['users'],'Faturamento'=>money($counts['revenue'])] as $label=>$value): ?><div class="col-6 col-lg-3"><div class="stat-card"><span class="muted small"><?= $label ?></span><strong><?= $value ?></strong></div></div><?php endforeach; ?></div><h2 class="admin-title mb-3">PEDIDOS RECENTES</h2><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Pagamento</th><th>Total</th><th>Itens</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= $o['id'] ?></td><td><?= e($o['customer']) ?></td><td><?= date('d/m/Y H:i',strtotime($o['created_at'])) ?></td><td><?= e($o['payment_method']) ?></td><td><?= money($o['total']) ?></td><td><a href="order.php?id=<?= $o['id'] ?>" class="text-danger">Ver itens</a></td></tr><?php endforeach; ?></tbody></table></div></div></section><?php include '../includes/footer.php'; ?>
